class Solution:
    def minOperationsToMakeMedianK(self, nums: List[int], k: int) -> int:
        nums.sort()
        n, ans = len(nums), 0
        m = n // 2
        if nums[m] > k:
            for i in range(m, -1, -1):
                if nums[i] <= k: break
                ans += nums[i] - k
        elif nums[m] < k:
            for i in range(m, n):
                if nums[i] >= k: break
                ans += k - nums[i]
        return ans

