class Solution {
public:
    long long minOperationsToMakeMedianK(vector<int>& nums, int k) {
        sort(nums.begin(), nums.end());
        int n = nums.size(), m = n / 2;
        long long ans = 0;
        if (nums[m] > k)
            for (int i = m; i >= 0 && nums[i] > k; i--) ans += nums[i] - k;
        else
            for (int i = m; i < n && nums[i] < k; i++) ans += k - nums[i];
        return ans;
    }
};

