var minOperationsToMakeMedianK = function(nums, k) {
    nums.sort((a, b) => a - b);
    const n = nums.length, m = n >> 1;
    let ans = 0;
    if (nums[m] > k) {
        for (let i = m; i >= 0 && nums[i] > k; i--) ans += nums[i] - k;
    } else {
        for (let i = m; i < n && nums[i] < k; i++) ans += k - nums[i];
    }
    return ans;
};
